<script>
const billingClaimSelect=document.getElementById('sub-claim'),billingCardSelect=document.getElementById('sub-card');
function filterBillingCards(){const claimId=billingClaimSelect.value;for(const option of billingCardSelect.options){if(!option.value)continue;option.hidden=option.dataset.claim!==claimId;if(option.hidden&&option.selected)billingCardSelect.value='';}if(!billingCardSelect.value)billingCardSelect.selectedIndex=0;}
billingClaimSelect?.addEventListener('change',filterBillingCards);filterBillingCards();
</script>
@endif
